{
  "vulnerable_symbols": [
    "yaml.full_load",
    "yaml.load"
  ],
  "trigger": "应用使用 PyYAML 5.3 的 yaml.full_load 或 yaml.load(..., Loader=FullLoader) 解析攻击者可控的 YAML 数据时触发。",
  "preconditions": [
    "PyYAML 版本为 5.3（<5.3.1）",
    "使用 FullLoader（yaml.full_load 或 yaml.load(..., Loader=FullLoader)）"
  ],
  "exploit_evidence": [
    {
      "src": 1,
      "kind": "poc",
      "quote": "data=load(content,Loader=FullLoader)# Using vulnerable FullLoader"
    },
    {
      "src": 4,
      "kind": "poc",
      "quote": "data = load(content, Loader=FullLoader) # Using vulnerable FullLoader"
    }
  ],
  "fixed_version": "5.3.1",
  "summary_zh": "PyYAML 5.3 FullLoader 解析不可信 YAML 可 RCE，升级 5.3.1。"
}
